// Sequential circuit with combinational logic in the feedback loop. The
// output of the flip-flop has been made observable through the output
// state. The circuit performs a simple counter that goes from 0 to 7,
// then wraps around to 0.
module TopModule(
  input  clk,
  input  a,
  input  b,
  output reg q,
  output reg state
);
  reg [2:0] cnt;
  wire [2:0] next_cnt;
  always @(*) next_cnt = cnt + 1;
  always @(posedge clk) begin
    cnt <= next_cnt;
    q <= (cnt == 3);
    state <= (cnt == 7);
  end
  always @(*) if (a) cnt <= 0;
  always @(*) if (b) cnt <= 4;
endmodule

